import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { fetchNews } from "../api";

export default function NewsList() {
  const [articles, setArticles] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchNews({ limit: 12 })
      .then((d) => {
        setArticles(d.articles || []);
      })
      .catch(console.error)
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="news-loading">Đang tải tin tức...</div>;

  return (
    <div className="news-page container">
      <h1>Tin tức BĐS mới nhất</h1>
      <div className="news-grid">
        {articles.map((art) => (
          <Link to={`/news/${art.id}`} key={art.id} className="news-card">
            <div className="news-thumb" style={{ backgroundImage: `url(${art.thumbnail || "/placeholder.jpg"})` }} />
            <div className="news-info">
              <h3 className="news-title">{art.title}</h3>
              <p className="news-meta">{art.source} • {art.publishedAt ? new Date(art.publishedAt).toLocaleString() : ""}</p>
              <p className="news-excerpt">{art.excerpt}</p>
            </div>
          </Link>
        ))}
      </div>
    </div>
  );
}
